If it helps, think of handling the damage via TheDamageHandlingProgram(tm), whose pseudocode is:

ApplyDamageToVampire ( vampire v, unsigned int normal, unsigned int aggravated )
{
while( normal > 0)
{
if (v.blood > 0) v.blood--
else v.wounded = true
normal--
}
while( aggravated > 0)
{
if( not v.wounded ) v.wounded = true
else if (v.blood > 0) v.blood--
else v.burned = true
aggravated--
}

if (v.burned) Burn(v)
else if(v.wounded) SendToTorpor(v)
}
